import{_ as a,o as t,c as s,a0 as i}from"./chunks/framework.CnTYizyl.js";const g=JSON.parse('{"title":"Hosted Login Pages","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/hosted-login.md","filePath":"guide/deployment/hosted-login.md"}'),o={name:"guide/deployment/hosted-login.md"};function n(r,e,d,l,h,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="hosted-login-pages" tabindex="-1">Hosted Login Pages <a class="header-anchor" href="#hosted-login-pages" aria-label="Permalink to &quot;Hosted Login Pages&quot;">​</a></h1><p>Authup serves its own login, consent, registration and password pages on the IdP origin. An application never renders a login form: it sends the browser to <code>/authorize</code>, and everything up to the redirect back with a <code>code</code> happens on these pages. They are rendered by <code>@authup/server-auth-console</code>, which <code>authup start</code> runs on the same listener as the API. In a <a href="./console-replicas.html">split deployment</a>, <code>authup start console auth</code> runs it alone.</p><table tabindex="0"><thead><tr><th>Page</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>Login and consent</td><td><code>/authorize</code></td><td>Sign in, complete a second factor, grant consent</td></tr><tr><td>Registration</td><td><code>/register</code></td><td>Create an account (when enabled)</td></tr><tr><td>Activation</td><td><code>/activate</code></td><td>Confirm the email address of a new account</td></tr><tr><td>Password forgot</td><td><code>/password-forgot</code></td><td>Request a password reset mail</td></tr><tr><td>Password reset</td><td><code>/password-reset</code></td><td>Set a new password with the mailed code</td></tr><tr><td>Sign-out</td><td><code>/logout</code></td><td>RP-initiated logout (see <a href="./../development/api-oauth2.html#_6-rp-initiated-logout">OAuth2</a>)</td></tr><tr><td>Device verification</td><td><code>/device</code></td><td>Approve a device (see <a href="./../development/api-oauth2.html#_8-device-authorization-grant-rfc-8628">OAuth2</a>)</td></tr></tbody></table><p>Each path is answered by the API with a redirect to the same page under the auth console&#39;s URL (<code>&lt;publicUrl&gt;/console/auth</code> by default), carrying the query unchanged. A <code>POST</code> to the same path (<code>/register</code>, <code>/password-forgot</code>, ...) is the JSON API the page itself calls, so a custom front end can drive the same flows without the hosted pages.</p><p>The pages can be rebranded with a <a href="./theming.html">theme</a>, and replaced entirely by substituting the package (<code>authConsole.path</code>).</p><h2 id="choosing-a-realm" tabindex="-1">Choosing a realm <a class="header-anchor" href="#choosing-a-realm" aria-label="Permalink to &quot;Choosing a realm&quot;">​</a></h2><p>A user belongs to exactly one realm, and a user name is only unique within its realm. Every login therefore happens against one realm, and where that realm comes from depends on who started the login.</p><p><strong>An application&#39;s authorize request pins the realm.</strong> The login form on <code>/authorize</code> authenticates users of the client&#39;s own realm and shows no realm picker. A client identified by its id needs nothing more. A client identified by its name must be accompanied by the realm, because every realm can hold a client of that name:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /authorize?client_id=my-app&amp;realm_id=&lt;realm id or name&gt;&amp;...</span></span></code></pre></div><p>A user of another realm cannot sign in to that client. A lingering session of another realm is shown as such, with an option to sign in with a different account.</p><p><strong>The consoles pick the realm first.</strong> The admin console and the <a href="./account-console.html">account console</a> show a realm chooser to a visitor without a session, and start the login against the chosen realm&#39;s system client. A deployment with a single realm skips the chooser. A link to the account console can pin the realm up front with <code>&lt;publicUrl&gt;/console/account?realmId=&lt;id or name&gt;</code>.</p><p><strong>A login without a client shows a realm picker on the form.</strong> The device verification page is the one hosted page that signs in without an authorization request, so its login form lets the user pick the realm.</p><p>A token requested directly (the password grant, see <a href="./../development/api-oauth2.html#_1-password-flow">OAuth2</a>) takes the realm as <code>realm_id</code> / <code>realm_name</code> and falls back to the master realm when none is given.</p><h2 id="registration" tabindex="-1">Registration <a class="header-anchor" href="#registration" aria-label="Permalink to &quot;Registration&quot;">​</a></h2><p>Self-registration is off by default. Turn it on with:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">core</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    registrationEnabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>(<code>core.registrationEnabled</code> / <code>REGISTRATION_ENABLED</code>.) The login form then links to <code>/register</code>, which asks for a user name, an email address and a password. The password must be at least <code>core.passwordMinLength</code> characters long (<code>PASSWORD_MIN_LENGTH</code>, default 10).</p><p>The account is created in the realm of the login it was started from: the link from <code>/authorize</code> carries the client&#39;s realm as <code>realmId</code>. A registration without a realm, for example a direct <code>POST /register</code>, creates the user in the master realm.</p><p>With registration disabled, <code>/register</code> shows a &quot;not enabled&quot; notice instead of the form, and <code>POST /register</code> is refused with the error code <code>registration_disabled</code>.</p><h3 id="email-verification" tabindex="-1">Email verification <a class="header-anchor" href="#email-verification" aria-label="Permalink to &quot;Email verification&quot;">​</a></h3><p>By default a registered account is active immediately and the user can sign in right away. To require a confirmed email address first, also enable email verification and configure <a href="./configuration-server-core-smtp.html">SMTP</a>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">core</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    registrationEnabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    emailVerificationEnabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">smtp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;smtps://user:password@smtp.example.com&#39;</span></span></code></pre></div><p>A registration then creates an inactive account and mails an activation code. The mail links to <code>&lt;publicUrl&gt;/activate?token=&lt;code&gt;</code>, which activates the account and marks the email address as verified. An inactive account cannot sign in. If the mail cannot be sent, the account is removed again and the registration fails, so a failed delivery never leaves an account nobody can activate.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Without an <code>smtp</code> setting, mails are discarded silently rather than failing. Registration with email verification then succeeds, but no activation mail arrives and the account stays inactive. Always configure SMTP together with email verification.</p></div><h2 id="password-recovery" tabindex="-1">Password recovery <a class="header-anchor" href="#password-recovery" aria-label="Permalink to &quot;Password recovery&quot;">​</a></h2><p>Password recovery is off by default and needs email verification as well, because the reset code is delivered by mail:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">core</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    passwordRecoveryEnabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    emailVerificationEnabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">smtp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;smtps://user:password@smtp.example.com&#39;</span></span></code></pre></div><p>(<code>PASSWORD_RECOVERY_ENABLED</code>, <code>EMAIL_VERIFICATION_ENABLED</code>.) With recovery enabled but email verification off, a reset request is refused with the error code <code>email_verification_required</code>.</p><p>The flow:</p><ol><li>The login form links to <code>/password-forgot</code>. The user enters their user name or email address.</li><li>Authup mails a reset code, valid for 30 minutes. The mail links to <code>&lt;publicUrl&gt;/password-reset?token=&lt;code&gt;&amp;realmId=&lt;realm&gt;</code>.</li><li>On <code>/password-reset</code> the user enters their user name or email address again and chooses a new password (at least <code>core.passwordMinLength</code> characters).</li></ol><p>A code that has run out is refused with <code>reset_token_expired</code>; the user starts again from step 1. With recovery disabled, both pages show a &quot;not enabled&quot; notice and the endpoints refuse with <code>password_recovery_disabled</code>.</p><h2 id="returning-to-the-application" tabindex="-1">Returning to the application <a class="header-anchor" href="#returning-to-the-application" aria-label="Permalink to &quot;Returning to the application&quot;">​</a></h2><p>Every link from the login form to another page carries the original authorize request as a <code>redirect</code> parameter, so &quot;back to login&quot; on the registration, activation or password pages resumes the application&#39;s sign-in rather than ending on a dead end. The parameter only accepts a path on the Authup origin, never an absolute URL.</p><h2 id="feature-flags" tabindex="-1">Feature flags <a class="header-anchor" href="#feature-flags" aria-label="Permalink to &quot;Feature flags&quot;">​</a></h2><p>Which of these flows are enabled is public. The status endpoint (<code>GET /</code>) reports them under <code>features</code>, next to the console flags; see <a href="./../development/api-introduction.html#status-endpoint">API</a>. The hosted pages read the same flags to decide which links to show.</p>`,35)])])}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
